package rules; import java.util.ArrayList;import java.util.Collections;import java.util.LinkedHashMap;import java.util.List;import java.util.Map; public final class IdsRule{private String action="alert";private String protocol="ip";private AddressExpression source=new AddressExpression("any");private PortExpression sourcePort=new PortExpression("any");private AddressExpression destination=new AddressExpression("any");private PortExpression destinationPort=new PortExpression("any");private String direction="->";private final Map<String,String> options=new LinkedHashMap<>();private final List<ContentOption> contents=new ArrayList<>();public String action(){return action;}public void action(String v){action=v;}public String protocol(){return protocol;}public void protocol(String v){protocol=v;}public AddressExpression source(){return source;}public void source(AddressExpression v){source=v;}public PortExpression sourcePort(){return sourcePort;}public void sourcePort(PortExpression v){sourcePort=v;}public AddressExpression destination(){return destination;}public void destination(AddressExpression v){destination=v;}public PortExpression destinationPort(){return destinationPort;}public void destinationPort(PortExpression v){destinationPort=v;}public String direction(){return direction;}public void direction(String v){direction=v;}public void option(String k,String v){options.put(k,v);if(k.equals("content"))contents.add(new ContentOption(v,options.containsKey("nocase")));}public Map<String,String> options(){return Collections.unmodifiableMap(options);}public List<ContentOption> contents(){return Collections.unmodifiableList(contents);}public String sid(){return options.getOrDefault("sid","");}public String msg(){return options.getOrDefault("msg","");}}
